function lt_config(){static $c;if(!$c){$path=dirname(__DIR__,2).'/private/leave-transfer/'.basename(__DIR__).'.json';if(!is_file($path))throw new RuntimeException('ชุด local ยังไม่ได้รับอนุญาตจากผู้เขียน');$c=json_decode(file_get_contents($path),true);if(empty($c['instance'])||empty($c['facility_code']))throw new RuntimeException('การติดตั้งไม่สมบูรณ์');}return $c;}
function lt_uuid($s){return is_string($s)&&preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iD',$s);}
function lt_new_uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);$h=bin2hex($b);return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20);}
function lt_json($v){return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);}
function lt_map($p,$kind,$key,$uuid=null){$s=$p->prepare('SELECT uuid FROM compensation_transfer_map WHERE kind=? AND local_key=?');$s->execute([$kind,(string)$key]);$old=$s->fetchColumn();if($old){if($uuid&&strtolower($old)!==strtolower($uuid))throw new RuntimeException('UUID ถูกเชื่อมไว้แล้ว ห้ามเปลี่ยนคนอัตโนมัติ');return $old;}if($kind==='person'&&!$uuid)throw new RuntimeException('ADMIN ต้องเชื่อม UUID บุคลากรจาก cloud ก่อน ไม่จับคู่จากชื่อ');$uuid=$uuid?:lt_new_uuid();$p->prepare('INSERT INTO compensation_transfer_map(kind,local_key,uuid) VALUES(?,?,?)')->execute([$kind,(string)$key,$uuid]);return $uuid;}
function lt_person($p,$pid){$s=$p->prepare('SELECT id,full_name,facility_code FROM compensation_personnel WHERE id=? AND active=1');$s->execute([$pid]);$person=$s->fetch();$c=lt_config();if(!$person||$person['facility_code']!==$c['facility_code']||!canAccessPersonnelRow($person)||!isUnitManager())throw new RuntimeException('ไม่มีสิทธิ์รับส่งข้อมูลบุคลากรนอกหน่วยที่ผู้เขียนอนุญาต');return $person;}
function lt_detail_fields(){return ['note','reference_no','written_date','written_at','addressee','form_employment_type','form_position_name','form_position_level','form_work_unit','form_section','form_division','contact_address','contact_phone','delegate_name','submission_channel','decision_note'];}
function lt_details_validate($details){$limits=['note'=>500,'reference_no'=>100,'written_date'=>10,'written_at'=>200,'addressee'=>200,'form_employment_type'=>100,'form_position_name'=>200,'form_position_level'=>100,'form_work_unit'=>200,'form_section'=>200,'form_division'=>200,'contact_address'=>500,'contact_phone'=>50,'delegate_name'=>200,'submission_channel'=>10,'decision_note'=>500,'full_name'=>1000,'vacation_grant'=>20,'vacation_carry'=>20,'approval_reference'=>1000,'approved_by_name'=>1000,'approval_date'=>10];foreach($details as $k=>$v){if(!isset($limits[$k])||!is_string($v)||mb_strlen($v)>$limits[$k])throw new RuntimeException('ข้อความช่อง '.$k.' เกินขนาดที่ local รองรับหรือชนิดไม่ถูกต้อง จึงไม่ตัดข้อความทิ้ง');if(in_array($k,['written_date','approval_date'],true)&&$v!=='')lt_date($v);if(in_array($k,['vacation_grant','vacation_carry'],true)&&$v!==''&&(!is_numeric($v)||(float)$v<0||(float)$v>366||fmod((float)$v,.5)!=0))throw new RuntimeException('สิทธิพักผ่อนไม่ถูกต้อง');}if(isset($details['submission_channel'])&&!in_array($details['submission_channel'],['online','paper'],true))throw new RuntimeException('ช่องทางยื่นไม่ถูกต้อง');}
