 }
 $s=$p->prepare('SELECT e.quota_days,e.note,t.code FROM compensation_leave_entitlements e JOIN compensation_leave_types t ON t.id=e.leave_type_id WHERE personnel_id=? AND fiscal_year=? ORDER BY t.code');$s->execute([$pid,$fy]);$qs=$s->fetchAll();if($qs){$q=[];$notes=[];foreach($qs as $e){$q[$e['code']]=(float)$e['quota_days'];if($e['note'])$notes[]=$e['note'];}$records[]=['kind'=>'quota','id'=>lt_map($p,'quota',$pid.':'.$fy),'revision'=>1,'data'=>['quotas'=>(object)$q,'note'=>implode(' · ',array_unique($notes))]];}
