function lt_validate($packet,$snap){if(($packet['format']??'')!=='kelang-leave-transfer'||($packet['schema_version']??0)!==1||!lt_uuid($packet['package_id']??null)||($packet['source_instance']??'')!==lt_config()['trusted_source']||($packet['facility_code']??'')!==$snap['person']['facility_code']||($packet['person']['facility_code']??'')!==$snap['person']['facility_code']||($packet['person']['id']??'')!==$snap['person']['id']||($packet['fiscal_year']??0)!==$snap['year']||!isset($packet['records'])||!is_array($packet['records'])||count($packet['records'])>1012||strlen(lt_json($packet))>2200000)throw new RuntimeException('แฟ้ม/แหล่งข้อมูล/บุคลากร/หน่วย/ปีไม่ตรงกับชุดที่ผู้เขียนอนุญาต');}
function lt_array($v){return json_decode(lt_json($v),true);}
function lt_equal($a,$b){return lt_canonical($a)===lt_canonical($b);}
function lt_canonical($v){if(is_object($v)){$v=get_object_vars($v);ksort($v);foreach($v as &$x)$x=json_decode(lt_canonical($x));return lt_json((object)$v);}if(is_array($v)){if(array_keys($v)!==range(0,count($v)-1)&&count($v)){ksort($v);}foreach($v as &$x)$x=json_decode(lt_canonical($x));}return lt_json($v);}
function lt_plan($p,$pid,$fy,$packet){$snap=lt_snapshot($p,$pid,$fy);lt_validate($packet,$snap);$hash=hash('sha256',lt_json($packet));$s=$p->prepare('SELECT packet_hash FROM compensation_transfer_receipts WHERE package_id=?');$s->execute([$packet['package_id']]);$old=$s->fetchColumn();if($old){if($old!==$hash)throw new RuntimeException('package_id เดิมแต่เนื้อหาต่างกัน');return ['duplicate'=>true,'token'=>hash('sha256',lt_json($snap)),'items'=>[]];}
